<tr><td class="style_td" style="text-align:center;"><span style="color:#3366ff">剛毅</span></td><td class="style_td">レヴィ・フランクル</td><td class="style_td"><span style="color:#c0c0c0">（タロットでは「力」）</span></td><td class="style_td" style="text-align:center;">太陽</td><td class="style_td">　</td><td class="style_td">　</td></tr>
